param([switch]$InstallGuicedEE)
$ErrorActionPreference = 'Stop'
$workspace = Split-Path $PSScriptRoot -Parent
if ($InstallGuicedEE) {
    # Optional explicit preparation; keeps framework builds outside the measurement window.
    foreach ($module in @('bom/Versioner','bom/StandaloneBOM','bom','services/Libraries/firebase-admin','services/Libraries/okio','services/Libraries/zstd-jni','services/Libraries/commercetools','client','vertx','inject','telemetry','web','rest','fault-tolerance','metrics','openapi','swagger-ui')) {
        & mvn -B -f "$workspace/GuicedEE/$module/pom.xml" install '-DskipTests' '-Dmaven.javadoc.skip=true'
        if ($LASTEXITCODE) { throw "Framework build failed: $module" }
    }
}
& mvn -B -f "$PSScriptRoot/pom.xml" clean install
if ($LASTEXITCODE) { throw 'Benchmark build failed' }
foreach ($application in @('guicedee','guicedee-scan')) {
    & mvn -B -f "$PSScriptRoot/$application/pom.xml" dependency:build-classpath '-Dmdep.outputFile=target/classpath.txt' '-Dmdep.regenerateFile=true'
    if ($LASTEXITCODE) { throw "Classpath resolution failed: $application" }
}
& npm ci --prefix "$PSScriptRoot/fixtures/firebase" --ignore-scripts --no-audit
if ($LASTEXITCODE) { throw 'Emulator tooling installation failed' }
& node "$PSScriptRoot/fixtures/firebase/node_modules/firebase-tools/lib/bin/firebase.js" setup:emulators:firestore
if ($LASTEXITCODE) { throw 'Emulator download failed' }

param([string]$Tag = 'local', [string]$TraceDirectory)
$ErrorActionPreference = 'Stop'
$benchmarkRoot = Split-Path $PSScriptRoot -Parent
$suiteRoot = Split-Path $benchmarkRoot -Parent
foreach ($module in @('GuicedEE/services/Google/guice-core', 'GuicedEE/native-image', 'GuicedEE/openapi', 'GuicedEE/swagger-ui')) {
    & mvn -B -ntp -f (Join-Path $suiteRoot "$module/pom.xml") install '-Dmaven.javadoc.skip=true'
    if ($LASTEXITCODE) { throw "Native support build failed: $module" }
}
$prepare = Join-Path $benchmarkRoot 'tools/prepare_guicedee_native.py'
if ($TraceDirectory) { & python $prepare $TraceDirectory } else { & python $prepare }
if ($LASTEXITCODE) { throw 'Native metadata/staged SDK validation failed' }
& docker build --target guicedee-native -t "devsuite-bench-guicedee-native:$Tag" -f "$PSScriptRoot/Dockerfile" $benchmarkRoot
if ($LASTEXITCODE) { throw 'GuicedEE native image build failed' }

param([string]$Tag = 'phases', [switch]$UpdateOpenApi, [switch]$GuicedeeOnly)
$ErrorActionPreference = 'Stop'
$benchmarkRoot = Split-Path $PSScriptRoot -Parent
$workspace = Split-Path $benchmarkRoot -Parent

# Keep the existing staged SDK snapshot; never consume a half-written host SDK JAR.
& mvn -B -ntp -f "$workspace/GuicedEE/inject/pom.xml" package '-DskipTests' '-Dmaven.javadoc.skip=true'
if ($LASTEXITCODE) { throw 'Diagnostic inject packaging failed' }
$prepareArguments = @()
if ($UpdateOpenApi) {
    & mvn -B -ntp -f "$workspace/GuicedEE/openapi/pom.xml" package '-DskipTests' '-Dmaven.javadoc.skip=true'
    if ($LASTEXITCODE) { throw 'OpenAPI packaging failed' }
    $prepareArguments += '--update-openapi'
}
& python "$benchmarkRoot/tools/prepare_phase_build.py" @prepareArguments
if ($LASTEXITCODE) { throw 'Phase input preparation failed' }
foreach ($entry in @(
    @{ Target = 'guicedee-jlink'; Image = 'guicedee-jlink' },
    @{ Target = 'guicedee-scan-jlink'; Image = 'guicedee-scan-jlink' },
    @{ Target = 'phase-quarkus'; Image = 'quarkus' }
)) {
    if ($GuicedeeOnly -and $entry.Image -eq 'quarkus') { continue }
    & docker build --target $entry.Target -t "devsuite-bench-$($entry.Image):$Tag" -f "$PSScriptRoot/Dockerfile" $benchmarkRoot
    if ($LASTEXITCODE) { throw "Phase image build failed: $($entry.Image)" }
}

param([switch]$Native)
$ErrorActionPreference = 'Stop'
$benchmarkRoot = Split-Path $PSScriptRoot -Parent
foreach ($application in @('guicedee','guicedee-scan')) {
$libraryDir = Join-Path $benchmarkRoot "$application/target/lib"
if (Test-Path -LiteralPath $libraryDir) {
    $resolvedLibraryDir = (Resolve-Path -LiteralPath $libraryDir).Path
    $expectedLibraryDir = [IO.Path]::GetFullPath($libraryDir)
    if ($resolvedLibraryDir -ne $expectedLibraryDir -or !$resolvedLibraryDir.StartsWith($benchmarkRoot + [IO.Path]::DirectorySeparatorChar)) {
        throw 'Dependency output is outside the benchmark workspace'
    }
    Remove-Item -LiteralPath $resolvedLibraryDir -Recurse -Force
}
& mvn -B -f "$benchmarkRoot/$application/pom.xml" dependency:copy-dependencies '-DincludeScope=runtime' "-DoutputDirectory=$libraryDir"
if ($LASTEXITCODE) { throw 'Runtime dependency packaging failed' }
}
& python "$benchmarkRoot/tools/prepare_jlink.py"
if ($LASTEXITCODE) { throw 'Modular application artifact validation failed' }
if ($Native) {
    & python "$benchmarkRoot/tools/prepare_native_metadata.py"
    if ($LASTEXITCODE) { throw 'SDK native metadata preparation failed' }
    & python "$benchmarkRoot/tools/prepare_native.py"
    if ($LASTEXITCODE) { throw 'Native/JVM adapter parity validation failed' }
}
& python "$benchmarkRoot/tools/stage_link_repository.py"
if ($LASTEXITCODE) { throw "Local Maven repository staging failed" }
& python "$benchmarkRoot/tools/image_provenance.py"
if ($LASTEXITCODE) { throw 'Image input capture failed' }
$variants = @('guicedee','guicedee-scan','quarkus','guicedee-jlink','guicedee-scan-jlink')
if ($Native) { $variants += 'quarkus-native' }
foreach ($framework in $variants) {
    & docker build --target $framework -t "devsuite-bench-${framework}:local" -f "$PSScriptRoot/Dockerfile" $benchmarkRoot
    if ($LASTEXITCODE) { throw "Image build failed: $framework" }
}
if ($Native) {
    & "$PSScriptRoot/build-guicedee-native.ps1"
    if ($LASTEXITCODE) { throw 'GuicedEE native image build failed' }
}

