"""Capture packaged inputs and fixture sources before building immutable benchmark images."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def capture():
    sources = []
    for path in ROOT.rglob('*'):
        relative = path.relative_to(ROOT)
        if any(part in ['target', 'node_modules', 'repository', 'results', '.idea', '__pycache__', 'analysis'] for part in relative.parts):
            continue
        if path.is_file() and (path.suffix in ['.java', '.py', '.xml', '.properties', '.ps1', '.sh']
                              or path.name in ['Dockerfile', '.env', 'jlink-modules.txt','native-metadata-inputs.json','native-trace-inputs.json'] or 'META-INF' in relative.parts):
            data = path.read_bytes()
            sources.append({'path': relative.as_posix(), 'sha256': hashlib.sha256(data).hexdigest(),
                            'content': data.decode('utf-8')})
    jars = []
    for directory in [ROOT/'guicedee/target', ROOT/'guicedee-scan/target', ROOT/'quarkus/target/quarkus-app', ROOT/'quarkus-native/target/quarkus-app']:
        for path in directory.rglob('*.jar'):
            jars.append({'path': path.relative_to(ROOT).as_posix(),
                         'sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
    wrappers=[]
    for name in ['firebase-admin','commercetools']:
        directory=ROOT.parent/'GuicedEE/services/Libraries'/name
        for relative in ['pom.xml','src/moditect/module-info.java']:
            path=directory/relative
            if path.is_file():
                data=path.read_bytes()
                wrappers.append({'path':path.relative_to(ROOT.parent).as_posix(),
                                 'sha256':hashlib.sha256(data).hexdigest(),'content':data.decode('utf-8')})
    return {'sourcesAtImageBuild': sources, 'packagedJars': jars, 'sdkWrapperSources':wrappers,
            'note': 'Source snapshot at image packaging; build the Maven reactor before packaging images.'}


if __name__ == '__main__':
    (ROOT/'docker/build-provenance.json').write_text(json.dumps(capture(), indent=2)+'\n', encoding='utf-8')

"""Retain observed SDK reflection/resources from a passing diagnostic agent run."""
import hashlib
import json
import os
from pathlib import Path
import sys
import zipfile

ROOT=Path(__file__).resolve().parents[1]


def verify_sdk_inputs(traced,current):
    if not traced or {e['name']:e['sha256'] for e in traced}!={e['name']:e['sha256'] for e in current}:
        raise ValueError('Traced Docker SDKs differ from local SDKs; rebuild the Quarkus JVM image and retrace')


def main():
    if len(sys.argv)!=2: raise SystemExit('Usage: import_native_trace.py <agent-output-directory>')
    directory=Path(sys.argv[1])
    diagnostic=json.loads((directory/'diagnostic.json').read_text())
    if not diagnostic.get('allCapabilitiesPassed'): raise SystemExit('All workload checks must pass before importing a trace')
    source=directory/'reachability-metadata.json'
    metadata=json.loads(source.read_text())
    entries=set()
    inputs=[]
    for path in (ROOT/'guicedee/target/classpath.txt').read_text().strip().split(os.pathsep):
        jar=Path(path)
        if jar.name not in ['commercetools-2.5.1.jar','firebase-admin-2.5.1.jar']:continue
        with zipfile.ZipFile(jar) as archive: entries.update(archive.namelist())
        inputs.append({'name':jar.name,'sha256':hashlib.sha256(jar.read_bytes()).hexdigest()})
    verify_sdk_inputs(diagnostic.get('sdkJars'),inputs)
    classes={entry[:-6].replace('/','.') for entry in entries if entry.endswith('.class')}
    selected={'reflection':[entry for entry in metadata.get('reflection',[])
                            if isinstance(entry.get('type'),str) and entry['type'].removesuffix('[]') in classes],
              'resources':[entry for entry in metadata.get('resources',[]) if entry.get('glob') in entries]}
    # The JVM agent observes class-name queries for optional OpenSSL exception
    # types. Retain these only with their backend; otherwise native-image roots
    # the outer engine's initializer, which cannot run without tcnative either.
    for entry in selected['reflection']:
        if entry['type'].startswith('com.commercetools.internal.shaded.io.netty.handler.ssl.ReferenceCountedOpenSsl'):
            entry['condition']={'typeReached':'com.commercetools.internal.shaded.io.netty.internal.tcnative.SSL'}
    target=ROOT/'quarkus-native/src/main/resources/META-INF/native-image/dev.guicedee.benchmarks/sdk-trace'
    target.mkdir(parents=True,exist_ok=True)
    (target/'reachability-metadata.json').write_text(json.dumps(selected,indent=2)+'\n')
    (ROOT/'quarkus-native/native-trace-inputs.json').write_text(json.dumps({
        'agentSha256':diagnostic['agentSha256'],'traceSha256':hashlib.sha256(source.read_bytes()).hexdigest(),
        'allCapabilitiesPassed':True,'sdkJars':inputs,'included':{key:len(value) for key,value in selected.items()},
        'scope':'Only types and resources owned by the two SDK wrapper JARs; no workload code changes'},indent=2)+'\n')
    print('Imported SDK reachability metadata:',{key:len(value) for key,value in selected.items()})


if __name__=='__main__':main()

import java.lang.module.*;
import java.util.*;

/** Inspect the installed image without loading application classes or dropping SPI providers. */
public class LinkGraphAudit {
    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            throw new IllegalArgumentException("Usage: LinkGraphAudit <application-module>");
        }
        var finder = ModuleFinder.ofSystem();
        var roots = Set.of(args[0]);
        var required = Configuration.empty().resolve(finder, ModuleFinder.of(), roots);
        var bound = Configuration.empty().resolveAndBind(finder, ModuleFinder.of(), roots);
        var requiredNames = names(required);
        var boundNames = names(bound);
        var modules = new TreeMap<String, Object>();
        for (var ref : finder.findAll()) {
            var descriptor = ref.descriptor();
            var requires = new TreeMap<String, Object>();
            for (var dependency : descriptor.requires()) {
                requires.put(dependency.name(), Map.of("static", dependency.modifiers().contains(ModuleDescriptor.Requires.Modifier.STATIC),
                        "transitive", dependency.modifiers().contains(ModuleDescriptor.Requires.Modifier.TRANSITIVE)));
            }
            long bytes = 0;
            long entries = 0;
            try (var reader = ref.open(); var resources = reader.list()) {
                for (var name : resources.toList()) {
                    var data = reader.read(name);
                    if (data.isPresent()) {
                        var buffer = data.get();
                        bytes += buffer.remaining();
                        entries++;
                        reader.release(buffer);
                    }
                }
            }
            var providers = new TreeMap<String, Object>();
            for (var provider : descriptor.provides()) providers.put(provider.service(), provider.providers());
            modules.put(descriptor.name(), Map.of("requires", requires, "uses", new TreeSet<>(descriptor.uses()),
                    "provides", providers, "resourceBytesUncompressed", bytes, "resourceCount", entries,
                    "requiredFromApplication", requiredNames.contains(descriptor.name()),
                    "reachableWithServiceBinding", boundNames.contains(descriptor.name())));
        }
        System.out.println(json(Map.of("root", args[0], "requiredClosure", requiredNames,
                "serviceBoundClosure", boundNames, "modules", modules)));
    }

    private static Set<String> names(Configuration configuration) {
        var result = new TreeSet<String>();
        for (var module : configuration.modules()) result.add(module.name());
        return result;
    }

    private static String json(Object value) {
        if (value instanceof String text) return "\"" + text.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
        if (value instanceof Map<?, ?> map) {
            var items = new ArrayList<String>();
            for (var entry : map.entrySet()) items.add(json(entry.getKey()) + ":" + json(entry.getValue()));
            return "{" + String.join(",", items) + "}";
        }
        if (value instanceof Collection<?> list) {
            var items = new ArrayList<String>();
            for (var item : list) items.add(json(item));
            return "[" + String.join(",", items) + "]";
        }
        return String.valueOf(value);
    }
}

import java.lang.module.ModuleFinder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;

/** Fingerprint installed jimage modules without resolving/initializing application classes. */
public class ModuleFingerprint {
    public static void main(String[] args) throws Exception {
        for (var reference : ModuleFinder.ofSystem().findAll().stream()
                .sorted(java.util.Comparator.comparing(r -> r.descriptor().name())).toList()) {
            var moduleHash = MessageDigest.getInstance("SHA-256");
            long bytes = 0;
            int count = 0;
            try (var reader = reference.open(); var names = reader.list()) {
                for (String name : names.sorted().toList()) {
                    var entry = reader.open(name);
                    if (entry.isEmpty()) continue;
                    var contentHash = MessageDigest.getInstance("SHA-256");
                    try (var input = entry.get()) {
                        byte[] buffer = new byte[16384];
                        int read;
                        while ((read = input.read(buffer)) != -1) {
                            contentHash.update(buffer, 0, read);
                            bytes += read;
                        }
                    }
                    moduleHash.update(name.getBytes(StandardCharsets.UTF_8));
                    moduleHash.update((byte) 0);
                    byte[] digest = contentHash.digest();
                    moduleHash.update(digest);
                    if (args.length > 0 && reference.descriptor().name().equals(args[0]))
                        System.out.println("RESOURCE\t"+name+"\t"+HexFormat.of().formatHex(digest));
                    count++;
                }
            }
            System.out.println(reference.descriptor().name()+"\t"+count+"\t"+bytes+"\t"+HexFormat.of().formatHex(moduleHash.digest()));
        }
    }
}

"""Relocate embedded SDK native-image metadata using the SDK wrappers' actual shade rules."""
import hashlib
import json
import os
from pathlib import Path
import re
import xml.etree.ElementTree as ET
import zipfile

ROOT=Path(__file__).resolve().parents[1]
NS={'m':'http://maven.apache.org/POM/4.1.0'}


def rules(pom):
    result=[]
    for relocation in ET.parse(pom).findall('.//m:relocation',NS):
        source=relocation.findtext('m:pattern',namespaces=NS)
        target=relocation.findtext('m:shadedPattern',namespaces=NS)
        exclusions=[e.text.removesuffix('.**') for e in relocation.findall('m:excludes/m:exclude',NS)]
        result.append((source,target,exclusions))
    return sorted(result,key=lambda r:len(r[0]),reverse=True)


def relocate(text, relocations):
    def name(value):
        separator='/' if '/' in value else '.'
        dotted=value.replace('/','.')
        for source,target,excluded in relocations:
            if (dotted==source or dotted.startswith(source+'.')) and not any(dotted==e or dotted.startswith(e+'.') for e in excluded):
                return (target+dotted[len(source):]).replace('.',separator)
        return value
    # Protect Java regex quoting while mapping its quoted resource/package name.
    text=text.replace('\\Q','\\Q ')
    text=re.sub(r'(?:[A-Za-z_$][\w$]*[./])+[A-Za-z_$][\w$]*',lambda m:name(m.group()),text)
    return text.replace('\\Q ','\\Q')


def transform(value, relocations):
    if isinstance(value,str): return relocate(value,relocations)
    if isinstance(value,list): return [transform(v,relocations) for v in value]
    if isinstance(value,dict): return {k:transform(v,relocations) for k,v in value.items()}
    return value


def optional_logging(value):
    # google-http-client registers an optional Commons Logging adapter even without Log4j 1.x.
    # Querying all its methods requires the absent backend. Retain it conditionally instead.
    if isinstance(value,list):
        for entry in value:
            if isinstance(entry,dict) and entry.get('name','').endswith('.org.apache.commons.logging.impl.Log4JLogger'):
                prefix=entry['name'].split('org.apache.commons.logging.impl.Log4JLogger')[0]
                entry.setdefault('condition',{'typeReachable':prefix+'org.apache.log4j.Logger'})
    return value


def prepare():
    dependencies=[Path(p) for p in (ROOT/'guicedee/target/classpath.txt').read_text().strip().split(os.pathsep)]
    base=ROOT/'quarkus-native/src/main/resources/META-INF/native-image/dev.guicedee.benchmarks'
    traced=json.loads((base/'sdk-trace/reachability-metadata.json').read_text())
    observed_types={entry['type'] for entry in traced['reflection'] if isinstance(entry.get('type'),str)}
    manifest=[]
    for sdk in ['firebase-admin','commercetools']:
        jar=next(p for p in dependencies if p.name==sdk+'-2.5.1.jar')
        pom=ROOT.parent/'GuicedEE/services/Libraries'/sdk/'pom.xml'
        relocations=rules(pom)
        with zipfile.ZipFile(jar) as z:
            # Quarkus disables GraalVM's automatic ServiceLoader feature. Keep the
            # shaded SDK descriptors and register provider constructors explicitly.
            services=[]
            providers=[]
            for entry in z.namelist():
                if not entry.startswith('META-INF/services/') or entry.endswith('/'):
                    continue
                service=entry.removeprefix('META-INF/services/')
                services.append({'pattern':r'\Q'+entry+r'\E'})
                implementations=[line.split('#',1)[0].strip() for line in z.read(entry).decode('utf-8').splitlines()]
                # Retain every provider of an exercised SPI. Unused SDK products
                # need their own trace before claiming native capability coverage.
                if any(provider in observed_types for provider in implementations):
                    for provider in filter(None,implementations):
                        providers.append({'name':provider,'condition':{'typeReachable':service},
                                          'methods':[{'name':'<init>','parameterTypes':[]}]})
            service_dir=base/sdk/'sdk-services'
            service_dir.mkdir(parents=True,exist_ok=True)
            (service_dir/'resource-config.json').write_text(json.dumps({'resources':{'includes':services}},indent=2)+'\n')
            (service_dir/'reflect-config.json').write_text(json.dumps(providers,indent=2)+'\n')
            for entry in z.namelist():
                if not entry.startswith('META-INF/native-image/') or entry.endswith('/'):
                    continue
                if not entry.endswith(('.json','.properties')): continue
                source=z.read(entry).decode('utf-8')
                output=(json.dumps(optional_logging(transform(json.loads(source),relocations)),indent=2)+'\n'
                        if entry.endswith('.json') else relocate(source,relocations))
                target=base/sdk/entry.removeprefix('META-INF/native-image/')
                target.parent.mkdir(parents=True,exist_ok=True)
                target.write_text(output,encoding='utf-8')
        manifest.append({'sdk':sdk,'jarSha256':hashlib.sha256(jar.read_bytes()).hexdigest(),
                         'shadePomSha256':hashlib.sha256(pom.read_bytes()).hexdigest()})
    (ROOT/'quarkus-native/native-metadata-inputs.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print('Relocated SDK native-image metadata; original metadata is excluded only during native compilation.')


