"""Summarize instrumented runs without promoting them to performance comparisons."""
import argparse
import collections
import json
from pathlib import Path
import statistics


def binding_dot(snapshot):
    lines=['digraph injector {', '  rankdir=LR;', '  node [shape=box];']
    for binding in snapshot['bindings']:
        label=binding['type']+'\n'+binding['module']
        if binding.get('interceptedMethods'): label+='\nAOP: '+', '.join(m['method'] for m in binding['interceptedMethods'])
        lines.append('  '+json.dumps(binding['id'])+' [label='+json.dumps(label)+
                     ',color='+('black' if binding['explicit'] else 'blue')+'];')
        for dependency in binding.get('dependencies',[]):
            if dependency['bindingId']!='not-in-snapshot':
                lines.append('  '+json.dumps(binding['id'])+' -> '+json.dumps(dependency['bindingId'])+';')
    return '\n'.join(lines+['}'])+'\n'


def summarize(directories):
    grouped=collections.defaultdict(list)
    for directory in directories:
        summary=json.loads((directory/'summary.json').read_text())
        if not summary.get('instrumented') or summary['eligibleComparison'] or not summary.get('allDiagnosticsPassed'):
            raise ValueError('Expected a passing diagnostic batch, never a ranked comparison: '+str(directory))
        for row in summary['runs']:
            if not row['phaseEvidence']['verified'] or not row['capabilitiesPassed']:
                raise ValueError('Missing capability or phase evidence')
            grouped[row['variant']].append((directory,row))
    result={'instrumented':True,'performanceComparison':False,'variants':{},
            'note':'Inclusive phase durations overlap. Guice graph is a runtime binding snapshot, not whole-program reachability.'}
    for variant,entries in grouped.items():
        startup=collections.defaultdict(list)
        workload=collections.defaultdict(list)
        inventories=[]
        for directory,row in entries:
            core=row['phaseEvidence']['startup']
            if core:
                per_run=collections.Counter()
                for event in core['events']: per_run[event['phase']]+=event['durationNs']/1e6
                for phase,milliseconds in per_run.items(): startup[phase].append(milliseconds)
                scan=core['scan']
                inventories.append({'scanPerformed':scan['performed'],'scannedClasses':scan.get('classCount',0),
                    'scanModules':sorted(m['name'] for m in scan.get('moduleSources',[])),
                    'classOrigins':sorted({c['origin'] for c in scan.get('classes',[])}),
                    'resourcesByOrigin':scan.get('resourcesByOrigin',{}),
                    'bindings':core['injector']['bindingCount'], 'explicitBindings':core['injector']['explicitBindingCount']})
                (directory/f"{variant}-{row['run']}-bindings.dot").write_text(binding_dot(core['injector']),encoding='utf-8')
            per_run_workload=collections.Counter()
            for operation in row['phaseEvidence']['workload']:
                for event in operation['events']: per_run_workload[event['phase']]+=event['durationNs']/1e6
            for phase,milliseconds in per_run_workload.items(): workload[phase].append(milliseconds)
        result['variants'][variant]={'runs':len(entries),
            'startupMedianMs':{k:statistics.median(v) for k,v in sorted(startup.items())},
            'workloadMedianMs':{k:statistics.median(v) for k,v in sorted(workload.items())},
            'inventories':inventories,
            'workloadConstructionsPerRun':[sum(o['operation']=='workload-construction' for o in row['phaseEvidence']['workload']) for _,row in entries],
            'rows':[str(directory/f"{variant}-{row['run']}.json") for directory,row in entries],
            'imageIds':sorted({row['container']['image'] for _,row in entries})}
    return result


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directories',nargs='+',type=Path)
    parser.add_argument('--output',required=True,type=Path)
    args=parser.parse_args()
    result=summarize(args.directories)
    args.output.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')
    for name,data in result['variants'].items():
        print(name, 'runs='+str(data['runs']))
        print('Startup:',{k:round(v,2) for k,v in data['startupMedianMs'].items() if not k.startswith(('provision:','pre-hook','post-hook'))})
        print('SDK:',{k:round(v,2) for k,v in data['workloadMedianMs'].items()})
        if data['inventories']: print('Inventory:',data['inventories'][0])

"""Deterministic OAuth/commercetools fixture. It validates and records real SDK traffic."""
import collections
import json
import socket
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


class Upstream(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, host="127.0.0.1"):
        super().__init__((host, 0), Handler)
        self.events = []
        self.counts = collections.Counter()
        self.lock = threading.Lock()

    def record(self, method, path, status):
        with self.lock:
            self.events.append({"method": method, "path": path, "status": status})


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def setup(self):
        super().setup()
        self.connection.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)

    def log_message(self, *_): pass

    def handle(self):
        try: super().handle()
        except (ConnectionResetError, BrokenPipeError): pass

    def reply(self, status, body):
        self.server.record(self.command, self.path, status)
        data = json.dumps(body).encode() if not isinstance(body, str) else body.encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        try: self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError): pass

    def do_POST(self):
        raw = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        if self.path == "/oauth/token":
            valid = self.headers.get("Authorization") == "Basic Zml4dHVyZTpmaXh0dXJl" and b"grant_type=client_credentials" in raw
            return self.reply(200 if valid else 401, {"access_token": "fixture-token", "token_type": "Bearer", "expires_in": 3600})
        if self.path == "/benchmark/graphql":
            try: valid = "inventoryEntries" in json.loads(raw)["query"]
            except (ValueError, KeyError): valid = False
            valid &= self.headers.get("Authorization") == "Bearer fixture-token"
            return self.reply(200 if valid else 400, {"data": {"inventoryEntries": {"results": [{"availableQuantity": 40}]}}})
        self.reply(404, {"error": "unknown fixture path"})

    def do_GET(self):
        if self.path == "/benchmark":
            if self.headers.get("Authorization") != "Bearer fixture-token": return self.reply(401, {})
            return self.reply(200, {"key": "benchmark", "name": "Fixture shop", "version": 1,
                                   "createdAt": "2026-01-01T00:00:00Z", "currencies": ["ZAR"], "countries": ["ZA"], "languages": ["en"]})
        if self.path.startswith("/flaky/"):
            with self.server.lock:
                self.server.counts[self.path] += 1
                count = self.server.counts[self.path]
            return self.reply(503 if count < 3 or self.path.endswith("always") else 200, "ok")
        if self.path == "/slow":
            threading.Event().wait(0.25)
            return self.reply(200, "late")
        self.reply(404, {})

"""Explicit artifacts and runtime modes used by the comparison matrix."""


def select_variants(framework='both', discovery='both', runtime='jre', native=False):
    bases = []
    if framework in ['both', 'guicedee']:
        if discovery in ['both', 'spi']: bases.append(('guicedee', 'guicedee', 'spi'))
        if discovery in ['both', 'scan']: bases.append(('guicedee-scan', 'guicedee', 'scan'))
    if framework in ['both', 'quarkus']: bases.append(('quarkus', 'quarkus', None))
    modes = ['jre', 'jlink'] if runtime == 'both' else [] if runtime == 'native' else [runtime]
    variants = [{'id': name + ('-jlink' if mode == 'jlink' else ''), 'framework': family,
             'discovery': discovery_mode, 'runtime': mode}
            for mode in modes for name, family, discovery_mode in bases
            if mode != "jlink" or family == "guicedee"]
    if native or runtime == 'native':
        if framework in ['both','guicedee'] and discovery in ['both','spi']:
            variants.append({'id':'guicedee-native','framework':'guicedee','discovery':'spi','runtime':'native'})
        if framework in ['both','quarkus']:
            variants.append({'id':'quarkus-native', 'framework':'quarkus', 'discovery':None, 'runtime':'native'})
    return variants


def runtime_flags(variant, flags):
    # Native has no tiered JIT. Keep heap and processor controls equal and record the distinction.
    return [flag for flag in flags if not flag.startswith('-XX:TieredStopAtLevel=')] if variant['runtime']=='native' else list(flags)


def ordered_variants(variants, run):
    # Rotate each pair of rounds, reversing the second. Rotating on every round
    # AND reversing canceled out for two variants, always running SPI first.
    shift = ((run - 1) // 2) % len(variants)
    order = variants[shift:] + variants[:shift]
    return order if run % 2 else list(reversed(order))


def paired_image_variants(variants, baseline_tag, candidate_tag):
    if baseline_tag == candidate_tag:
        raise ValueError('Baseline and candidate tags must differ')
    if any(v['runtime']=='native' for v in variants):
        raise ValueError('Paired image comparisons currently support JVM variants only')
    return [dict(v,id=v['id']+'-'+role,imageArtifact=v['id'],imageTag=tag,comparisonRole=role)
            for v in variants for role,tag in [('before',baseline_tag),('after',candidate_tag)]]


def guicedee_jar(variant):
    return 'comparison-' + guicedee_project(variant) + '-1.0-SNAPSHOT.jar'


def guicedee_project(variant):
    if variant['runtime']=='native': return 'guicedee-native'
    return 'guicedee-scan' if variant['discovery'] == 'scan' else 'guicedee'

